import numpy as np
import random

def calculate_sum(adj):
    n = len(adj)
    degrees = np.sum(adj, axis=1)
    s = 0
    for i in range(n):
        for j in range(i + 1, n):
            if adj[i, j]:
                s += abs(degrees[i] - degrees[j])
    return s

def solve_hill_climbing(n=11):
    adj = np.zeros((n, n), dtype=int)
    # Initial random graph
    for i in range(n):
        for j in range(i + 1, n):
            if random.random() < 0.5:
                adj[i, j] = adj[j, i] = 1

    current_sum = calculate_sum(adj)
    improved = True
    while improved:
        improved = False
        edges = [(i, j) for i in range(n) for j in range(i + 1, n)]
        random.shuffle(edges)
        for i, j in edges:
            adj[i, j] = adj[j, i] = 1 - adj[i, j]
            new_sum = calculate_sum(adj)
            if new_sum > current_sum:
                current_sum = new_sum
                improved = True
            else:
                adj[i, j] = adj[j, i] = 1 - adj[i, j]
    return current_sum

max_found = 0
for _ in range(100):
    res = solve_hill_climbing(11)
    if res > max_found:
        max_found = res

print(f"Max found: {max_found}")

